package com.franco.desco.adapter.in.web.catalog;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.catalog.CatalogCommands.*;import com.franco.desco.application.catalog.port.in.CatalogUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/catalogos") @Tag(name="Catálogos",description="Catálogos maestros administrables.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated public class CatalogController{private final CatalogUseCase u;private final CatalogWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CatalogController(CatalogUseCase u,CatalogWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping @PreAuthorize("@permissionGuard.has(authentication,'CATALOGOS_LISTAR')") @Operation(operationId="catalogosListar",summary="Listar valores de catálogo") public ResponseEntity<ApiResponse<PageResponse<CatalogResponses.Item>>>list(@RequestParam String catalogo,@RequestParam(defaultValue="1") @Min(1) int pagina,@RequestParam(defaultValue="20") @Min(1) @Max(100) int tamano,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.list(map.list(catalogo,pagina,tamano),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @PostMapping @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CATALOGOS_CREAR')") @Operation(operationId="catalogosCrear",summary="Registrar valor") public ResponseEntity<ApiResponse<CatalogResponses.Created>>create(@Valid @RequestBody CatalogRequests.Create q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.create(map.command(q),ids.resolve(a),meta.resolve(r)),r,CatalogResponses.Created::new);}
 @PutMapping("/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CATALOGOS_EDITAR')") @Operation(operationId="catalogosEditar",summary="Editar valor") public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Update q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/deshabilitar") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CATALOGOS_RETIRAR')") @Operation(operationId="catalogosDeshabilitar",summary="Deshabilitar valor") public ResponseEntity<ApiResponse<Void>>disable(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Disable q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.disable(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
}
